const VIEWBOX = "80 91 2319 2368";

// sweep timing (seconds) – the bar moves linearly from left to right,
// each piece is timed to appear exactly when the bar reaches it.
const T0 = 0.25;       // sweep start
const SPAN = 1.9;      // sweep duration
const OVER = 0.1;      // bar starts 10 % before the logo and ends 10 % after
const reach = (fx: number) => +(T0 + ((fx + OVER) / (1 + 2 * OVER)) * SPAN).toFixed(3);

function Svg({ piece, fill, className = "", style }: {
  piece: Piece; fill: string; className?: string; style?: React.CSSProperties;
}) {
  const [d, t] = piece;
  return (
    <svg className={`pa-layer ${className}`} viewBox={VIEWBOX} fill={fill} aria-hidden="true" style={style}>
      <path d={d} transform={t} />
    </svg>
  );
}

/** pops in when the sweep reaches it */
function Pop({ piece, fill, className = "pa-pop", lead = 0 }: {
  piece: Piece; fill: string; className?: string; lead?: number;
}) {
  const [, , ox, oy, fx] = piece;
  return (
    <Svg
      piece={piece} fill={fill} className={className}
      style={{ transformOrigin: `${ox}% ${oy}%`, animationDelay: `${Math.max(0, reach(fx) - lead)}s` }}
    />
  );
}

/** revealed with a true left → right wipe (container + content slide in opposite directions) */
function Wipe({ piece, fill, from, to }: { piece: Piece; fill: string; from: number; to: number }) {
  const delay = reach(from);
  const dur = Math.max(0.3, reach(to) - delay);
  const st = { animationDelay: `${delay}s`, animationDuration: `${dur}s` };
  return (
    <div className="pa-wipe" style={st}>
      <div className="pa-wipe-in" style={st}>
        <Svg piece={piece} fill={fill} />
      </div>
    </div>
  );
}

export default function SplashScreen() {
  const [phase, setPhase] = useState<"show" | "exit" | "done">("show");

  useEffect(() => {
    const t1 = setTimeout(() => {
      setPhase("exit");
      // tell the rest of the page (3D phone etc.) that it can start loading now
      (window as any).__paSplashDone = true;
      window.dispatchEvent(new Event("pure-apple:splash-done"));
    }, 3200);
    const t2 = setTimeout(() => setPhase("done"), 4150);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  if (phase === "done") return null;
  const exiting = phase === "exit";

  const letters: [Piece, string][] = [
    ...PURE.map((p) => [p, "#4FAE53"] as [Piece, string]),
    ...APPLE.map((p) => [p, "#FCC10B"] as [Piece, string]),
  ];

  return (
    <div
      className={`pa-splash ${exiting ? "pa-exit" : ""}`}
      style={{ pointerEvents: exiting ? "none" : "auto" }}
    >
      <div className="pa-glow" />
      <span className="pa-dot pa-dot-1" />
      <span className="pa-dot pa-dot-2" />
      <span className="pa-dot pa-dot-3" />

      <div className="pa-center">
        <div className="pa-logo" role="img" aria-label="Pure Apple">
          {/* apple outline + shoulder: wiped in left → right */}
          <Wipe piece={OUTLINE}  fill="#FB5724" from={OUTLINE[4] - 0.33} to={OUTLINE[4] + 0.33} />
          <Wipe piece={SHOULDER} fill="#FB5724" from={SHOULDER[4] - 0.18} to={SHOULDER[4] + 0.18} />

          {/* leaf */}
          <Pop piece={STEM} fill="#4FAE53" className="pa-grow-up" />
          <Pop piece={LEAF} fill="#4FAE53" className="pa-leaf" lead={0.1} />

          {/* letters – pop in from left to right across both lines */}
          {letters.map(([p, c], i) => (
            <Pop key={i} piece={p} fill={c} />
          ))}

          {/* light bar travelling left → right */}
          <div className="pa-sweep" />
        </div>

        <div className="pa-tagline-wipe">
          <p className="pa-tagline">Better Tech, Brighter Tomorrow</p>
        </div>
      </div>

      <div className="pa-progress"><div className="pa-progress-bar" /></div>

      <style>{`
        .pa-splash {
          position: fixed; inset: 0; z-index: 9999;
          display: flex; flex-direction: column; align-items: center; justify-content: center;
          background: #ffffff; overflow: hidden;
          will-change: transform;
          transform: translateX(0);
        }
        /* exit: the whole panel slides off to the right */
        .pa-splash.pa-exit {
          transform: translateX(100%);
          box-shadow: -24px 0 48px rgba(15, 23, 42, 0.06);
          transition: transform 0.9s cubic-bezier(0.7, 0, 0.25, 1);
        }
        .pa-center { display: flex; flex-direction: column; align-items: center; }

        .pa-glow {
          position: absolute; width: min(560px, 110vw); aspect-ratio: 1; border-radius: 50%;
          background: radial-gradient(circle,
            rgba(251,87,36,0.07) 0%, rgba(252,193,11,0.05) 38%, rgba(79,174,83,0.03) 58%, transparent 72%);
          will-change: transform, opacity;
          animation: pa-glow-in 1.4s ease-out both;
        }
        .pa-dot { position: absolute; border-radius: 50%; opacity: 0; will-change: transform, opacity;
                  animation: pa-dot-float 3.2s ease-in-out infinite; }
        .pa-dot-1 { width: 10px; height: 10px; background: #FB5724; top: 30%; left: 24%; animation-delay: 0.6s; }
        .pa-dot-2 { width: 8px;  height: 8px;  background: #FCC10B; bottom: 30%; right: 26%; animation-delay: 1.1s; }
        .pa-dot-3 { width: 7px;  height: 7px;  background: #4FAE53; top: 38%; right: 22%; animation-delay: 1.6s; }

        .pa-logo { position: relative; width: min(260px, 62vw); aspect-ratio: 2319 / 2368; }
        .pa-layer {
          position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
          will-change: transform, opacity; backface-visibility: hidden;
        }

        /* true left → right wipe: container slides in from the left,
           its content slides in from the right by the same amount */
        .pa-wipe, .pa-wipe-in { position: absolute; inset: 0; }
        .pa-wipe    { overflow: hidden; will-change: transform;
                      animation: pa-wipe-box 1s cubic-bezier(0.4, 0, 0.6, 1) both; }
        .pa-wipe-in { will-change: transform;
                      animation: pa-wipe-content 1s cubic-bezier(0.4, 0, 0.6, 1) both; }

        /* letters / pieces pop in from the left as the bar reaches them */
        .pa-pop     { animation: pa-pop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both; }
        .pa-grow-up { animation: pa-grow-up 0.5s cubic-bezier(0.22, 1, 0.36, 1) both; }
        .pa-leaf {
          animation:
            pa-leaf-grow 0.9s cubic-bezier(0.34, 1.56, 0.64, 1) both,
            pa-sway 3.4s ease-in-out 2.6s infinite;
        }

        /* the light bar */
        .pa-sweep {
          position: absolute; top: -6%; bottom: -6%; left: -12%; width: 12%;
          background: linear-gradient(90deg,
            rgba(252,193,11,0) 0%, rgba(252,193,11,0.55) 40%, rgba(251,87,36,0.6) 60%, rgba(251,87,36,0) 100%);
          filter: blur(6px); pointer-events: none; will-change: transform, opacity;
          animation: pa-sweep ${SPAN}s linear ${T0}s both;
        }

        /* tagline: wiped in left → right */
        .pa-tagline-wipe { margin-top: 30px; overflow: hidden; will-change: transform;
                           animation: pa-wipe-box 0.9s cubic-bezier(0.4, 0, 0.2, 1) 1.75s both; }
        .pa-tagline {
          font-size: 12px; font-weight: 500; text-transform: uppercase;
          letter-spacing: 0.3em; padding-left: 0.3em;
          color: #9ca3af; text-align: center; white-space: nowrap;
          will-change: transform;
          animation: pa-wipe-content 0.9s cubic-bezier(0.4, 0, 0.2, 1) 1.75s both;
        }

        .pa-progress {
          position: absolute; bottom: 56px; width: 120px; height: 3px;
          border-radius: 9999px; background: #f3f4f6; overflow: hidden;
        }
        .pa-progress-bar {
          height: 100%; width: 100%; border-radius: 9999px; transform-origin: left;
          background: linear-gradient(90deg, #4FAE53, #FB5724, #FCC10B);
          will-change: transform;
          animation: pa-progress 3.1s cubic-bezier(0.4, 0, 0.2, 1) 0.1s both;
        }

        @keyframes pa-wipe-box     { from { transform: translateX(-100%); } to { transform: translateX(0); } }
        @keyframes pa-wipe-content { from { transform: translateX(100%); }  to { transform: translateX(0); } }
        @keyframes pa-pop {
          0%   { transform: translateX(-6%) translateY(4%) scale(0.6); opacity: 0; }
          100% { transform: translateX(0) translateY(0) scale(1);      opacity: 1; }
        }
        @keyframes pa-grow-up { from { transform: scaleY(0); opacity: 0; } to { transform: scaleY(1); opacity: 1; } }
        @keyframes pa-leaf-grow {
          0%   { transform: scale(0) rotate(-35deg); opacity: 0; }
          60%  { opacity: 1; }
          100% { transform: scale(1) rotate(0deg);  opacity: 1; }
        }
        @keyframes pa-sway { 0%, 100% { transform: rotate(0deg); } 50% { transform: rotate(3deg); } }
        @keyframes pa-sweep {
          0%   { transform: translateX(0);       opacity: 0; }
          8%   { opacity: 1; }
          92%  { opacity: 1; }
          100% { transform: translateX(1033%);   opacity: 0; }
        }
        @keyframes pa-glow-in { from { opacity: 0; transform: scale(0.7); } to { opacity: 1; transform: scale(1); } }
        @keyframes pa-dot-float {
          0%   { opacity: 0;   transform: translateY(10px); }
          30%  { opacity: 0.9; }
          70%  { opacity: 0.9; }
          100% { opacity: 0;   transform: translateY(-26px); }
        }
        @keyframes pa-progress { from { transform: scaleX(0); } to { transform: scaleX(1); } }

        @media (max-width: 480px) { .pa-tagline { font-size: 10px; } }
        @media (prefers-reduced-motion: reduce) {
          .pa-splash *, .pa-splash *::before { animation: none !important; }
          .pa-splash.pa-exit { transition-duration: 0.01s; }
        }
      `}</style>
    </div>
  );
}
